#include <iostream>
#include <vector>
#include <stdexcept>
int main() {
  const std::vector<int> notes{8, 12, 16};
  try {
    std::cout << notes.at(1) << "\n";
    std::cout << notes.at(9) << "\n";
  } catch (const std::out_of_range&) {
    std::cout << "Indice absent\n";
  }
}

#include <iostream>
#include <memory>
#include <utility>
struct Livre { int pages; };
int main() {
  auto premier = std::make_unique<Livre>(Livre{120});
  auto second = std::move(premier);
  std::cout << second->pages << " " << (premier == nullptr) << "\n";
}
